602: bool Leader::IsStableUpdated(uint8_t *aTlvs, uint8_t aTlvsLength, uint8_t *aTlvsBase, uint8_t aTlvsBaseLength)
603: {
604:     bool            rval = false;
605:     NetworkDataTlv *cur  = reinterpret_cast<NetworkDataTlv *>(aTlvs);
606:     NetworkDataTlv *end  = reinterpret_cast<NetworkDataTlv *>(aTlvs + aTlvsLength);
607: #if OPENTHREAD_ENABLE_SERVICE
608:     ServiceTlv *service;
609: #endif
610:
611:     while (cur < end)
612:     {
613:         VerifyOrExit((cur + 1) <= end && cur->GetNext() <= end);
614:
615:         switch (cur->GetType())
616:         {
617:         case NetworkDataTlv::kTypePrefix:
618:         {
619:             PrefixTlv *      prefix       = static_cast<PrefixTlv *>(cur);
620:             ContextTlv *     context      = FindContext(*prefix);
621:             BorderRouterTlv *borderRouter = FindBorderRouter(*prefix, true);
622:             HasRouteTlv *    hasRoute     = FindHasRoute(*prefix, true);
623:
624:             if (cur->IsStable() && (!context || borderRouter))
625:             {
626:                 PrefixTlv *prefixBase =
627:                     FindPrefix(prefix->GetPrefix(), prefix->GetPrefixLength(), aTlvsBase, aTlvsBaseLength);
628:
629:                 if (!prefixBase)
630:                 {
631:                     ExitNow(rval = true);
632:                 }
633:
634:                 if (borderRouter)
635:                 {
636:                     BorderRouterTlv *borderRouterBase = FindBorderRouter(*prefixBase, true);
637:
638:                     if (!borderRouterBase || memcmp(borderRouter, borderRouterBase, borderRouter->GetLength()) != 0)
639:                     {
640:                         ExitNow(rval = true);
641:                     }
642:                 }
643:
644:                 if (hasRoute)
645:                 {
646:                     HasRouteTlv *hasRouteBase = FindHasRoute(*prefixBase, true);
647:
648:                     if (!hasRouteBase || (memcmp(hasRoute, hasRouteBase, hasRoute->GetLength()) != 0))
649:                     {
650:                         ExitNow(rval = true);
651:                     }
652:                 }
653:             }
654:
655:             break;
656:         }
657:
658: #if OPENTHREAD_ENABLE_SERVICE
659:
660:         case NetworkDataTlv::kTypeService:
661:             service = static_cast<ServiceTlv *>(cur);
662:
663:             if (cur->IsStable())
664:             {
665:                 NetworkDataTlv *curInner;
666:                 NetworkDataTlv *endInner;
667:
668:                 ServiceTlv *serviceBase = FindService(service->GetEnterpriseNumber(), service->GetServiceData(),
669:                                                       service->GetServiceDataLength(), aTlvsBase, aTlvsBaseLength);
670:
671:                 if (!serviceBase || !serviceBase->IsStable())
672:                 {
673:                     ExitNow(rval = true);
674:                 }
675:
676:                 curInner = service->GetSubTlvs();
677:                 endInner = service->GetNext();
678:
679:                 while (curInner < endInner)
680:                 {
681:                     if (curInner->IsStable())
682:                     {
683:                         switch (curInner->GetType())
684:                         {
685:                         case NetworkDataTlv::kTypeServer:
686:                         {
687:                             bool       foundInBase = false;
688:                             ServerTlv *server      = static_cast<ServerTlv *>(curInner);
689:
690:                             NetworkDataTlv *curServerBase = serviceBase->GetSubTlvs();
691:                             NetworkDataTlv *endServerBase = serviceBase->GetNext();
692:
693:                             while (curServerBase <= endServerBase)
694:                             {
695:                                 ServerTlv *serverBase = static_cast<ServerTlv *>(curServerBase);
696:
697:                                 VerifyOrExit((curServerBase + 1) <= endServerBase && curServerBase->GetNext() <= end);
698:
699:                                 if (curServerBase->IsStable() && (server->GetServer16() == serverBase->GetServer16()) &&
700:                                     (server->GetServerDataLength() == serverBase->GetServerDataLength()) &&
701:                                     (memcmp(server->GetServerData(), serverBase->GetServerData(),
