703:                                 {
704:                                     foundInBase = true;
705:                                     break;
706:                                 }
707:
708:                                 curServerBase = curServerBase->GetNext();
709:                             }
710:
711:                             if (!foundInBase)
712:                             {
713:                                 ExitNow(rval = true);
714:                             }
715:
716:                             break;
717:                         }
718:
719:                         default:
720:                             break;
721:                         }
722:                     }
723:
724:                     curInner = curInner->GetNext();
725:                 }
726:             }
727:
728:             break;
729: #endif
730:
731:         default:
732:             break;
733:         }
734:
735:         cur = cur->GetNext();
736:     }
